// Send to MailMaven
// ------------------
// Drafts action Script step (macOS only — uses AppleScript).
//
// Behaviour:
//   * First line of the draft  -> email Subject
//   * Everything after line 1  -> email Body
//   * Opens MailMaven's composer (does NOT auto-send) so you can add
//     recipients and review before sending.
//
// Note on Markdown -> HTML:
//   MailMaven's AppleScript `content` property is *plain text only*
//   (per https://mailmaven.app/support/applescript/ — "Currently the
//   content is plain text only"). Injecting HTML would show literal
//   <p>/<a> tags in the message, so we deliberately pass the body as
//   readable plain text (the Markdown source). If MailMaven adds HTML
//   support later, swap `bodyText` for the rendered HTML from
//   MultiMarkdown.create().render(...) and set the appropriate property.

// --- 1. Split the draft into subject + body -----------------------------
let subject  = draft.processTemplate("[[title]]");   // first line
let bodyText = draft.processTemplate("[[body]]");    // remaining lines

if (subject.trim().length === 0) {
  app.displayWarningMessage("Draft is empty — nothing to send.");
  context.cancel();
}

// --- 2. Escape values for embedding in an AppleScript string literal -----
// Backslashes and double-quotes must be escaped; literal newlines are
// valid inside AppleScript quoted strings, so they can pass through as-is.
function asStr(s) {
  return '"' + String(s).replace(/\\/g, "\\\\").replace(/"/g, '\\"') + '"';
}

// --- 3. Build and queue the AppleScript ---------------------------------
let script = `
tell application "MailMaven"
	activate
	with transaction
		set newMsg to compose new message
		tell newMsg
			set subject to ${asStr(subject)}
			set content to ${asStr(bodyText)}
			show composer
		end tell
	end transaction
end tell
`;

let ok = app.queueAppleScript(script);
if (!ok) {
  context.fail("Failed to queue AppleScript for MailMaven.");
  app.displayErrorMessage("Could not hand the draft to MailMaven.");
}

