// Send to MailMaven  (macOS only — uses AppleScript)
// =====================================================
// First line of the draft  -> Subject
// Everything after line 1   -> Body (Markdown)
//
// HOW YOU GET HTML / FORMATTED MAIL
// ---------------------------------
// MailMaven's AppleScript exposes ONLY a plain-text `content` property on the
// composer (verified against MailMaven.sdef — there is no `html content`).
// Drafts is also sandboxed, so it can't shell out to build rich clipboard data.
//
// The clean path is therefore: hand MailMaven the *Markdown source* and let
// MailMaven render it to HTML. In MailMaven set the composer format to
// **Markdown** (composer format selector: Rich Text / Plain Text / Markdown —
// make Markdown the default). On send, the recipient gets real HTML.
//
// => Do NOT pre-render Markdown to HTML here. Passing HTML tags into a
//    plain-text / Markdown composer would show literal <p>/<a> markup.

// 1. Split subject (first line) from body (the rest).
let subject = draft.processTemplate("[[title]]");
let body    = draft.processTemplate("[[body]]");

if (subject.trim().length === 0) {
  app.displayWarningMessage("Draft is empty — nothing to send.");
  context.cancel();
}

// 2. Escape a JS string for a safe AppleScript string literal.
//    Backslash and double-quote must be escaped; newlines are legal inside
//    AppleScript quoted strings and pass through unchanged.
function asStr(s) {
  return '"' + String(s).replace(/\\/g, "\\\\").replace(/"/g, '\\"') + '"';
}

// 3. Build + queue the AppleScript. `show composer` opens the window for
//    review (add recipients, confirm) instead of auto-sending.
let script = `
tell application "MailMaven"
	activate
	with transaction
		set newMsg to compose new message
		tell newMsg
			set subject to ${asStr(subject)}
			set content to ${asStr(body)}
			show composer
		end tell
	end transaction
end tell
`;

if (!app.queueAppleScript(script)) {
  context.fail("Failed to queue AppleScript for MailMaven.");
  app.displayErrorMessage("Could not hand the draft to MailMaven.");
}

